const manifestTimes = `-- name: ManifestTimes :one
SELECT i.created_at::timestamptz AS intent_at,
 (i.created_at < statement_timestamp() - interval '30 days')::boolean AS outside,
 m.manifest_digest::text AS manifest_digest
FROM audit.manifest_intents i JOIN audit.export_manifests m ON m.chain_id=i.chain_id AND m.manifest_seq=i.manifest_seq
WHERE i.chain_id=$1::text AND i.manifest_seq=$2::bigint
`

type ManifestTimesParams struct {
	ChainID     string
	ManifestSeq int64
}

type ManifestTimesRow struct {
	IntentAt       pgtype.Timestamptz
	Outside        bool
	ManifestDigest string
}

// Verification window (TASK-07 3.2.1): the intent time is the signed
// manifest created_at; both timestamps are DB-assigned and immutable.
func (q *Queries) ManifestTimes(ctx context.Context, arg ManifestTimesParams) (ManifestTimesRow, error) {
	row := q.db.QueryRow(ctx, manifestTimes, arg.ChainID, arg.ManifestSeq)
	var i ManifestTimesRow
	err := row.Scan(&i.IntentAt, &i.Outside, &i.ManifestDigest)
	return i, err
}

