const retryBatchCandidates = `-- name: RetryBatchCandidates :many
SELECT b.batch_id FROM audit.export_batches b
WHERE b.destination=$1::text AND b.source_class=$2::text
AND EXISTS (SELECT FROM audit.export_batch_members m JOIN audit.audit_outbox o USING(record_kind,record_id,destination)
 WHERE m.batch_id=b.batch_id AND o.next_retry_at<=statement_timestamp()
 AND (o.state='pending' OR (o.state='claimed' AND o.lease_until<=statement_timestamp())))
ORDER BY b.created_at,b.batch_id LIMIT 100
`

type RetryBatchCandidatesParams struct {
	Destination string
	SourceClass string
}

func (q *Queries) RetryBatchCandidates(ctx context.Context, arg RetryBatchCandidatesParams) ([]pgtype.UUID, error) {
	rows, err := q.db.Query(ctx, retryBatchCandidates, arg.Destination, arg.SourceClass)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []pgtype.UUID
	for rows.Next() {
		var batch_id pgtype.UUID
		if err := rows.Scan(&batch_id); err != nil {
			return nil, err
		}
		items = append(items, batch_id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const retryOutboxMember = `-- name: RetryOutboxMember :execrows
UPDATE audit.audit_outbox SET state='pending',lease_until=NULL,next_retry_at=statement_timestamp()+make_interval(secs => $1::integer)
WHERE record_kind=$2::text AND record_id=$3::text AND destination=$4::text
AND state='claimed' AND attempts=$5::integer AND lease_until>statement_timestamp()
`

type RetryOutboxMemberParams struct {
	DelaySeconds int32
	RecordKind   string
	RecordID     string
	Destination  string
	Attempts     int32
}

func (q *Queries) RetryOutboxMember(ctx context.Context, arg RetryOutboxMemberParams) (int64, error) {
	result, err := q.db.Exec(ctx, retryOutboxMember,
		arg.DelaySeconds,
		arg.RecordKind,
		arg.RecordID,
		arg.Destination,
		arg.Attempts,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

